import he from 'he';
import { capitalize } from '../util.js';
import AbstractView from '../framework/view/abstract-view.js';
import { formatTime, formatDate, formatDateValue, formatDuration } from '../util.js';

const ROLLUP_BUTTON_CLASS_NAME = 'event__rollup-btn';
const FAVORITE_BUTTON_CLASS_NAME = 'event__favorite-btn';

function createTripTemplate({ point, offers, destination }) {
  const { basePrice, dateFrom, dateTo, type, isFavorite } = point;

  const favoriteClass = isFavorite ? `${FAVORITE_BUTTON_CLASS_NAME} event__favorite-btn--active` : `${FAVORITE_BUTTON_CLASS_NAME}`;

  const offersInfo = offers
    .map(
      (offer) =>
        `<li class="event__offer">
            <span class="event__offer-title">${offer.title}</span>
            &plus;&euro;&nbsp;
            <span class="event__offer-price">${offer.price}</span>
          </li>`,
    )
    .join('');

  return (
    /* HTML */
    `<li class="trip-events__item">
      <div class="event">
        <time class="event__date" datetime="${formatDateValue(dateFrom)}">${formatDate(dateFrom)}</time>
        <div class="event__type">
          <img class="event__type-icon" width="42" height="42" src="img/icons/${type}.png" alt="Event type icon" />
        </div>
        <h3 class="event__title">${capitalize(type)} ${he.encode(destination?.name ?? '')}</h3>
        <div class="event__schedule">
          <p class="event__time">
            <time class="event__start-time" datetime="${dateFrom}">${formatTime(dateFrom)}</time>
            &mdash;
            <time class="event__end-time" datetime="${dateTo}">${formatTime(dateTo)}</time>
          </p>
          <p class="event__duration">${formatDuration(dateFrom, dateTo)}</p>
        </div>
        <p class="event__price">&euro;&nbsp;<span class="event__price-value">${basePrice}</span></p>
        <h4 class="visually-hidden">Offers:</h4>
        <ul class="event__selected-offers">
          ${offersInfo}
        </ul>
        <button class="${favoriteClass}" type="button">
          <span class="visually-hidden">Add to favorite</span>
          <svg class="event__favorite-icon" width="28" height="28" viewBox="0 0 28 28">
            <path d="M14 21l-8.22899 4.3262 1.57159-9.1631L.685209 9.67376 9.8855 8.33688 14 0l4.1145 8.33688 9.2003 1.33688-6.6574 6.48934 1.5716 9.1631L14 21z" />
          </svg>
        </button>
        <button class="${ROLLUP_BUTTON_CLASS_NAME}" type="button">
          <span class="visually-hidden">Open event</span>
        </button>
      </div>
    </li>`
  );
}

export default class TripView extends AbstractView {
  #point = null;
  #offers = [];
  #destination = null;
  #handleRollupClick = null;
  #handleFavoriteClick = null;

  constructor({ point, offers, destination, onRollupClick, onFavoriteClick }) {
    super();
    this.#point = point;
    this.#offers = offers;
    this.#destination = destination;
    this.#handleRollupClick = onRollupClick;
    this.#handleFavoriteClick = onFavoriteClick;

    this.rollupButton.addEventListener('click', this.#rollupClickHandler);
    this.favoriteButton.addEventListener('click', this.#favoriteClickHandler);
  }

  get template() {
    return createTripTemplate({
      point: this.#point,
      offers: this.#offers,
      destination: this.#destination,
    });
  }

  get rollupButton() {
    return this.element.querySelector(`.${ROLLUP_BUTTON_CLASS_NAME}`);
  }

  get favoriteButton() {
    return this.element.querySelector(`.${FAVORITE_BUTTON_CLASS_NAME}`);
  }

  #rollupClickHandler = (evt) => {
    evt.preventDefault();
    this.#handleRollupClick?.();
  };

  #favoriteClickHandler = (evt) => {
    evt.preventDefault();
    this.#handleFavoriteClick?.();
  };
}
